INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1497912-stat212', 'stk-user9840', 'STAT 212', 'info', '{"desc": "بسم الله الرحمن الرحيم\nاقدر اقول اني ماقبل هذا الكورس كنت شيء ومابعده شيء آخر\nمن اهم وافضل 3 كورسات لطلاب البزنز …\n\nCH9\nHypothesis Tests for Means and Proportions. Tests for the Difference Between Two Means\n\nCH10\nTests for Two Populations Proportions\n\nCH12\nChi-squared Tests.\n\nCH13\nSimple Linear Regression\n\nCH14\nIntroduction to Multiple Regression\n\nCH15\nMultiple Regression Model Building\n\nCH16\nTime-Series Forecasting and Index Numbers\n\n>>>>>>>>>>>>>>>>>…\n\nالكورس يبدا بال Hypothesis Tests\n\nوفكرتها ان كثير من الاحيان يكون لدينا ادعاء او فكرة عن شيء ما فكيف ممكن نختبر الادعاء حقنا من خلال عدة اختبارات كيف نرى هل فعلا الادعاء حقنا صحيح ولالا …\nعلى سبيل المثال عندك فكرة ان مستوى استهلاك البنزين في الصيف يزيد فأنت تسوي اختبار وتشوف هل كلامك صحيح او لا بطريقة علمية\nمثال آخر عندك ادعاء ان جامعة البترول اصعب جامعة ههههه فأنت بتكنيك معين تسوي تست عشان تختبر صحة الادعاء هذا …\nطبعا هذا الفكرة الرئيسة للجباتر اللي في البداية وتتعمق بكل تأكيد اكثر كل ماتقدمت …\n\nجزء Regression model\nوهذا الشيء هو اللي يتمحور عليه الكورس بعمره\nفكيف تبني مودل او معادلة(Y=A+BX+B2XX) لأمر ما وكيف تختار العوامل اللي تؤثر على Y وكيف تختبر انك فعلا اخترت العوامل اللي مفروض تختارها وكيف بعدين تزيل كل الشوائب عن المودل بحيث في النهاية تبني مودل قوي متين يمكنك من التنبؤ بالعلومات بطريقة علمية رائعة …\n\nالموضوع متشعب جدا لكنه ممتع\nعلى سبيل المثال\nتبي تتنبئ بمستوى مبيعات النفط الصخري\nفأنت بتدور على العوامل اللي تؤثر على كمية انتاج النفط الصخري\nككمية انتاج اوبك +السعر الحالي للبرميل + الوضع الاقتصادي العام …ألخ\n\nوفي النهاية بعد عدة اختبارات راح توصل لافضل مودل للتنبؤ بمستوى الانتاج …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/stat-212-statistics-for-business-ii/120634/5", "user": "user9840", "ts": 1534597166000, "tid": 120634, "pn": 5}}', 1534597166000, 1794774616, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sadguts-stat212', 'stk-sadguts', 'STAT 212', 'doc', '{"docs": [{"id": "stk-dr-m68398", "n": "Dr. Mohammed Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "STAT212 - 203\nشريييييييييييييييييييييييييييييييييييييح قليلة فيه فاهم مرة وطريقة توصيله للمعلومة ممتازة\nاخلاقه حلوه يحب ينكت ويسولف ويطقطق شوي في الكلاس\nكويزاته متوسطة-صعبة ومقدور عليها وهوموركاته اصعب منها وطويلة لكن مفيدة\nمتساعد جدا في اوقات الكويزات والهوموركات وكل شيء يوضحه من بدري\nالميدتيرم كان متوسط والافرج كان 67% اتوقع لانه كان رتن وتصحيح الدكتور جدا ممتاز\nالفاينل كان صعب مرة وفيه تركات واظن السبب لانه MCQ الافرج كان تقريبا 52%\n\nالكورس بشكل عام اشوفه صعب لكن من امتع الكورسات الي درستها انصحك تخليه في ترم خفيف والدكتور شرحه بطل لو حصل لك لاتفوته اقدر اقول بدون تردد افضل واحد درسني من جيت الجامعة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531533-stat212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammed-saleh/68398/48", "user": "SadGuts", "ts": 1630069291000, "tid": 68398, "pn": 48}}]}', 1630069291000, 1794774616, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a_o_s_ll-stat212', 'stk-a_o_s_ll', 'STAT 212', 'doc', '{"docs": [{"id": "stk-dr-m68419", "n": "Dr. E. Al-Sawi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Stat212\n\nالتحضير : يحضر لكن مش مهتم بهالموضوع كثير…\n\nطريقة الشرح : يستخدم السلايدات لكنه يشرح عالبورد وشغله مرتب ويحاول\nيوصل الفكرة بقدر المستطاع ويتقبل الاسئلة مهما كانت “سخيفة” ومستعد\nيطير الكلاس كله عشان يشرح للطلاب مثال واحد اذا ما كانوا فاهمينه يعني\nانه رجل مهتم بالطلاب بشكل كبير جدا…\n\nالكويزات : قبل المياجر والفاينل يعني 3 كويزات خلال السمستر وكان مستواها\nعالي شوي لكن لها مغزى بالتحضير للمياجر…\n\nالمياجر: يحضر الطلاب للاختبارات بكويزات شوي صعبه وتلحس المخ بعض الاحيان\nعشان يدخلون الميجر وهم مصحصحين والمياجر نفس افكار الكويزات وتعتبر\nاسهل من الكويزات بمراحل…\n\nالفاينلات : نفس الكلام…\n\nالقريد النهائي: اعطيه A\n\nالصوت: لا بأس فيه ولغته نفس الكلام…\n\nإضافات: الدكتور متمكن من الكورس وفاهم لكن اللي لاحظته عليه ان لغته\nاو اختياره للالفاظ يخونه بالشرح بمعنى انه ممكن يشرح لك ويعطيك الفاظ\nولما يشرح شيء ثاني مرتبط بالاول تتفاجأ ان فيه تناقض بالسالفة بسبب\nاختياره ل الالفاظ المناسبه , انا اصنفه كأكثر دكتور يستحمل الاسئلة السخيفة\nهههههههههههه واحيانا اذا فصل بالشرح وتعمق يشرح بالعربي عشان توصل\nالمعلومة , حبوب واخلاق ويسولف كثير والحلو فيه انه يعرف الطالب بالاسم\nويحسسه بالاهتمام وان فيه احد فوق راسه…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1199505-stat212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/e-al-sawi/68419/26", "user": "A_O_S_ll", "ts": 1363285008000, "tid": 68419, "pn": 26}}]}', 1363285008000, 1794774616, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-stat212', 'stk-guest', 'STAT 212', 'doc', '{"docs": [{"id": "stk-dr-m68419", "n": "Dr. E. Al-Sawi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Stat212-Business Statistics II\n172\n\nالتحضير : يحضر يومياً على آخر الكلاس، مرة أو مرتين ماحضّر، متساهل بالتأخر (إلا إذا شاف تسيب).\nطريقة الشرح : يشرح الفكرة أو الكونسبت ثم يشرح كم مثال على السبورة، وماعنده مشكلة يخلص الكلاس على مثال واحد أهم شيء يشوف الطلاب فاهمين. أحيانًا ما يوصل لك الفكرة بس ترجع تشوف السلايدات تفهم.\nالكويزات : خيرنا بين (ميدتيرم وكويزات أو ثلاث مياجر بدون كويزات) اخترنا ثلاث مياجر.\nالمياجر: ثلاث مياجر كلها ريتن ، الأول عليه 15% متوسط الصعوبة والثاني والثالث أصعب عليها 20% 20%.\nالفاينلات : خيارات عليه 35% سهل عشان يرفع الطلاب لأن الأداء كان أقل من المأمول بالمياجر.\nالقريد النهائي: A\nالصوت: واضح\nإضافات: دكتور مرح وخفيف طينة ومتفهم للطلاب وحريص الله يجزاه خير. يتحمس بالشرح ويحاول يوصل المعلومة باللي يقدر، وشرحه أفضل إذا بدا الماتيريال اللي يحتاج اللاب.\nالهوموورك 5% اللاب تست 5%", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492237-stat212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/e-al-sawi/68419/41", "user": "Guest", "ts": 1526184954000, "tid": 68419, "pn": 41}}]}', 1526184954000, 1794774616, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-practice-stat212', 'stk-practice', 'STAT 212', 'doc', '{"docs": [{"id": "stk-dr-m68463", "n": "Dr. R. Anabosi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "STAT212 - TERM 152\n\n- طيب وبشوش\n- يعقد المادة بشكل غريب ويطولها لك\n- يطول في شرح النقطة لين يحسسك انها معقدة ودايم ما يطلعنا ع الوقت لدرجة الطلاب صارو يسحبو عليه ويطلعو\n- مياجره جدا صعبة والافرج يحكم ، اضطر بنهاية الترم يدف طلاب كثير يعني واحد التوتال حقه في الثلاثين تلقاه دي\n- يستغرب من ادأنا بالمياجر وما يعرف المشكلة وين ، المشكلة 100% في طريقة أسئلته ، بميجر 2 الهايست ما قرب من الفل مارك\n- ما انصح فيه ابدا تجربتي سيئة معاه ، كنت مو راضي بالصاوي بـ 211 لكن عرفت انه جنة جنب العنبوسي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1456244-stat212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/r-anabosi/68463/53", "user": "Practice", "ts": 1472628582000, "tid": 68463, "pn": 53}}]}', 1472628582000, 1794774616, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9921-stat212', 'stk-user9921', 'STAT 212', 'doc', '{"docs": [{"id": "stk-dr-m68463", "n": "Dr. R. Anabosi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Stat 212\nTerm 163\n\nالتحضير :\nبعد ٢٠ دقيقة من بداية الكلاس يىقّف الشرح ويحضر واللي يجي بعد كذا ليت\n\nطريقة الشرح :\nملفات بوربوينت فيها الأساسيات فقط ، ويستخدم ملفات إضافية يحطها ع البلاك ، يستخدم ملفات كثيييره وكذا يتلخبط الموضوع\n\nالكويزات :\nلايوجد\n\nالمياجر:\nكان يدرس كل السكاشن وكان يتفنن في الأسئلة الصعبة والتصحيح الرهيب!\nالمياجر اللي تجي كانت أصعب من الـ old exams ، وهو تصحيحه بعد شديييييد ما يعرف شي اسمه partial grade !\nوالوقت عنده كان ما يكففففي أبد ، كثير من الطلاب يترك أسئلة فاضية لأن الأسئلة نار والوقت المناسب ضعف اللي يحط!\nالأفرج الأول كان 60 والثاني 55 ! + ما فيه أحد من الطلاب وصل حتى قريب من الدرجة الكاملة\n\nالفاينلات :\nبعد الدرجات نااازلة صار الفاينل MCQs ، الأسئلة لازالت بصعوبتها لكن افتكينا من تصحيحه المريض\n\nالقريد النهائي:\nD\n\nالصوت:\nمفهوم إلا إذا صار مستعجل يطلع الياباني اللي في داخله\n\nإضافات :\nإذا انت راضي بقريد نازل وتبغى تشتغل كثييير نزّل معه ، الاختبارات كانت جحييم الدرجه اللي تتوقع تاخذها معاه قسمها على ٢ أو ٣\n\nاذا كان موجود أنصح أنك تبتعد عنه أو تأجّل المادة\n\n*", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479237-stat212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/r-anabosi/68463/54", "user": "user9921", "ts": 1503566175000, "tid": 68463, "pn": 54}}]}', 1503566175000, 1794774616, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9840-stat212', 'stk-user9840', 'STAT 212', 'doc', '{"docs": [{"id": "stk-dr-m68463", "n": "Dr. R. Anabosi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السلام عليكم …\nانا لما اول مرة دخلت لتقييم الاستاذ رائد العنبوسي شاهدت تفاوت كبير في الآراء لكن لما درست عنده\nانا شفت شخصين في جسد واحد شخص قبل الميجر 1 وشخص ثاني بعد الميجر 1 ههههههههههه…\n\nبسم الله نبدا بالتقييم قبل ميجر 1\nTERM 173 -STAT 212\n\nبنود التقييم :\n\nالتحضير :يحضر في نصف الكلاس واحيانا كثيرة ينسى والحضور ماعليه درجات ومتساهل نوعا ما فيه …\nطريقة الشرح :شرح بطل يشرح من السلايدات وفي نفس الوقت على الميني تاب ويحل امثلة كثيرة بحيث يبنيك صح ويزيل من عقلك اي تداخل ولخبطة في المعلومات بين الدروس والجباتر الزبد يفت لك الكونسبت صححححح…\nالكويزات :مافيه\nالمياجر:الميجر 1 كان متوسط الصعوبة وبحكم انه شرحه صح والله لو تدخل الاختبار على شرحه راح يكفي انك تطلع بدرجة مقبولة …\nالافرج 63\nالفاينلات : لسى يابعدي 😁\nالقريد النهائي: القريد النهائي له للفترة ماقبل الميجر الاول A+++++++++++++++++++++++\nالصوت: واضح واكسنت بطل …\nإضافات :\nمتعاون وخلوق مع الطلاب وماعمره طول لسانه على طالب او اهانه بل يعاملك كأبنه\nمن ناحية الاخلاق لاتدور عليه زلة …\n\nالتقييم من بعد الميجر الاول إلى الفاينل\nبنود التقييم :\n\nالتحضير : نفس الشيء ماتغير اسلوبه\nطريقة الشرح : فجأة تحول واصبح مايحل امثلة ولايشرح كويس والشرح عبارة عن تمرير سلايدات بالضبط نفس مواد الاسلامي والعربي …\n\nالمياجر: اصعب من الميجر الأول وتحتاج له سلف ستدي بحكم انه شرح كان سيءءءء جداااااااااااااااااااا\nالافرج 53\nالفاينلات :حرررررررررررررررررررررررريقة والله من اصعب الفاينلات اللي مرت علي في حياتي الجامعية حتى لو انك خاتم المنهج من A-Z\nلافرج ما قال لنا لكن ما استغرب لو كان 30 من 100\nالقريد النهائي: قريد الدكتور لما بعد الميجر 1 للفاينل\nF\n,F+ بحكم اخلاقه العالية …\n\nإضافات :\nطبعا هو دائما يدعي انه ديموقراطي وياخذ بآراء الطلاب لكن نظامه يكون انه يحشرك في زاوية ويقول لك تبيني اطعنك بسكين ولا اثور فيك برشاش هههههه\nفي الفاينل لاب كان يقول لنا مابتخافوا ابنائي انا الافرج عندي مابينزل عن 8 من 10 في اللاب تست\nوفجأة الافرج حقنا 4 ههههههههههههههه الزبدة لاتصدقونه …\nكذلك الفاينل جا وقال تراه سهل وندخل وهو جايب اسئلة من المريخ 😆\n\nكان فيه 5% للهومورك وما كان فيه قريدر فحتار وين يحطها \" في البداية قال بحطها لكم في درجة اعلى ميجر قلنا يلا اوك وفجأة يجي ويحطها على الفاينل\nوالفاينل ALREADY عليه 40% من الكورس بعد الاضافة صار 45% يعني شيء مهوووووول وغير طبيعي …\n\nتصحيحه في INTERPRETATION سيء لانه دايما يبيك تكتب اللي في باله …\n\nلكن للأمانة اضطر انه يدفنا في القريد النهائي دف طيب … فهو انسان طيب وانسان ماني بقايل في نفس الوقت هههههه …\n\nبس والله انه طييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييب وخلوق …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1497911-stat212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/r-anabosi/68463/59", "user": "user9840", "ts": 1534595894000, "tid": 68463, "pn": 59}}]}', 1534595894000, 1794774616, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-wael.h.b-stat212', 'stk-wael.h.b', 'STAT 212', 'doc', '{"docs": [{"id": "stk-dr-m68577", "n": "Dr. Mohammad Omar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "كورس stat212\n\nالتحضير : يحضر و مهتم في التحضير وكل تأخيرتين بدرجة غياب\n\nطريقة الشرح : على السبورة وعلى السلايدات\n\nالكويزات :سهالات يراجع الشابتر قبل ما يعطينا الكويز وبعدها يعطينا الكويز وتكون نفس الفكرة اللي هوا شرحها مع تغيير بسيط\n\nالمياجر: كومن ولكن طيب في التصحيح\n\nالفاينلات :كومن\n\nالقريد النهائي: الصراحة انا اعطيه a\n\nالصوت: عالي وواضح\n\nإضافات : الدكتور هذا مره حبيب ويبذل مجهوده عشان يوصل الفكرة للطالب ويحب الطلاب المهتمين. الصراحة انا لو عاد بي الزمن كنت حاخذ معاه مرة ثانية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p518426-stat212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-omar/68577/10", "user": "Wael.H.B", "ts": 1262867409000, "tid": 68577, "pn": 10}}]}', 1262867409000, 1794774616, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
